window.FILM_WORK_PROMPTS={"work_id":"src-649e9b43b303729a","records":[{"work_id":"src-649e9b43b303729a","frame_id":"FG-377002c6ec3b3460","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (817).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"黄昏或黎明时分，一名长发人物身穿深色厚外套，位于画面中央，背景是深紫色的天空与远处模糊的山脉轮廓。","analysis":"采用低角度仰拍构图，人物占据画面中心主要位置，仅可见头部至胸腹部，面部处于阴影中。背景天空呈现大面积深紫色调，地平线处有微弱的粉紫色光晕，远处山脉呈黑色剪影。整体光线昏暗，人物主体与背景形成剪影效果，色彩层次由深紫过渡到暗红。","prompt":"低角度仰拍视角，画面中央是一名长发人物的上半身剪影，身穿深色厚外套，面部隐没在阴影中。背景是广阔的深紫色天空，地平线附近透出微弱的粉紫色光晕，远处可见模糊的黑色山脉轮廓。整体色调阴郁，光线极暗，人物与背景形成强烈的明暗对比，呈现出黄昏或黎明时分的静谧氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:04-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (817).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.522,"observed_resolution":"normal","observation_limits":[],"id":"VP-292eea696339f1de","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-e13521e8ade530e0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (835).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"户外露台，左侧一人穿白色运动服站立，右侧一人穿红黑格纹长袍怀抱幼童，幼童手臂前伸，背景为茂密绿色山峦与天空。","analysis":"画面采用平视角度，构图平衡。左侧人物全身可见，右侧人物及幼童上半身清晰，下半身延伸至画面底部。背景山峦占据画面上半部约三分之一，植被茂密。光线为自然日光，色彩以绿色植被、白色衣物与红黑格纹为主，层次分明。","prompt":"户外露台场景，背景是郁郁葱葱的绿色山峦和淡蓝天空。左侧站立一名男子，身穿白色拉链运动外套，袖口有橙色条纹，下穿白色运动裤，双手在胸前持握白色物品。右侧站立一名男子，身穿红黑格纹长袍，怀抱一名幼童。幼童身穿蓝白条纹长袖，身体前倾，左臂向左侧男子伸出。地面为浅色石板，右侧边缘可见木质椅背。自然光照明，色彩饱和，画面清晰。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:12-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (835).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.514,"observed_resolution":"normal","observation_limits":[],"id":"VP-831d563c231674b5","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-6458766d5cc22b42","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (832).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"画面主体为一棵巨大的深绿色阔叶树，占据画面中央。树下阴影处站立着两个深色人影，周围是茂密的绿色灌木丛，背景为蓝天白云。","analysis":"构图上，大树位于画面正中，树冠宽阔，枝叶繁茂，几乎遮蔽了天空的大部分区域。树下有两个深色人影，身形较小，仅能辨识出站立的大致轮廓，具体面部和衣着细节不可见。环境光线明亮，天空呈现深蓝色，伴有几朵白云，树冠上方有轻微的光晕。整体色调偏冷，植被呈现暗绿色，光影对比明显，树下的阴影区域较深。","prompt":"这是一张户外自然风景的静帧画面。画面中央矗立着一棵巨大的阔叶树，树冠呈圆形，枝叶极其茂密，颜色为深绿色，几乎占据了画面的上半部分。在树干的底部阴影中，隐约可见两个深色的人影站立，身形较小，与巨大的树木形成对比。前景是大片茂密的绿色灌木和杂草，植被纹理清晰，呈现出一种野外荒地的质感。背景是晴朗的蓝天，点缀着几朵白色的积云。光线从上方照射，使得树冠顶部较亮，而树下和灌木丛深处则处于阴影中。画面整体色调偏冷，带有轻微的蓝色滤镜感，树冠上方有一处明显的光晕效果。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (832).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.489,"observed_resolution":"normal","observation_limits":[],"id":"VP-ff9f330dab83dbd7","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-dc28249f3bdbc08d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (815).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"两名男子在木质建筑前合力搬运一台白色机器，周围有茂密的芦苇和树木，地面铺设着花纹地砖。","analysis":"画面采用平视视角，构图平衡。两名男子全身可见，位于画面中景，相对大小适中。左侧男子穿白衬衫，右侧男子穿蓝T恤，两人身体前倾，共同抬起物体。环境占据大部分画面，包括上方的木质结构、右侧的高大芦苇和背景的绿树。光线柔和，色彩偏冷，呈现出一种自然、朴素的氛围。","prompt":"两名男子在户外木质建筑前搬运一台白色机器，左侧男子穿白衬衫和灰裤，右侧男子穿蓝T恤和深色裤，两人身体前倾，双手托住机器。建筑为木质结构，上方有横梁和悬挂的盆栽，左侧有一扇敞开的木门。右侧前景是一丛高大的白色芦苇，背景是茂密的绿树。地面铺设着带有花纹的地砖，前方是平整的水泥地。光线柔和，色彩偏冷，整体氛围自然朴素。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:27-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (815).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.509,"observed_resolution":"normal","observation_limits":[],"id":"VP-18d9fa02048af647","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-2aa6dd74311b31e2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (741).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"画面主体为一只人耳的局部特写，耳垂佩戴银色小圆环耳钉，周围环绕深色卷发，背景昏暗模糊，仅见极少量皮肤与发丝。","analysis":"构图极度紧凑，仅呈现人物头部侧面的一小部分，以耳朵为绝对视觉中心。人物身体其余部分完全不可见，环境占比极低且处于失焦状态。光线昏暗，整体色调偏冷且低饱和，明暗对比柔和，没有强烈的直射光，呈现出一种低调、私密的视觉氛围。","prompt":"这是一张极度贴近的局部特写画面，焦点清晰地落在一只人耳上。耳垂处佩戴着一枚细小的银色圆环耳钉，在昏暗的光线下反射出微弱的光泽。耳朵周围是深黑色的卷发，发丝质感在阴影中若隐若现。画面整体处于低照度环境中，色彩饱和度极低，呈现出一种冷调的暗色氛围。背景完全虚化，无法辨认具体环境，仅能隐约看到模糊的皮肤色块和深色阴影。构图紧凑，没有任何多余元素，视觉重心完全集中在耳朵的轮廓与耳饰细节上，营造出一种静谧且私密的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:35-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (741).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.467,"observed_resolution":"normal","observation_limits":[],"id":"VP-cdb3c43c4b11c8d5","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-ff0b7e0c4f1f2ebc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (817).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"画面主体为占据上方约三分之二的阴沉天空，云层厚重且呈深蓝色调。下方三分之一为纯黑色的山峦与树木剪影，右侧可见一棵树的轮廓，整体氛围压抑昏暗。","analysis":"构图上，黑色剪影位于底部，形成稳固的基底，上方大面积留白给天空。画面中无人物出现，主体为自然景物。光线极暗，主要光源似乎来自云层后方或缝隙，透出微弱的冷白光。色彩以深蓝、灰黑为主，明暗对比强烈，剪影部分完全无细节，天空部分有云层的纹理层次。","prompt":"这是一张极度昏暗的风景摄影作品。画面下方约三分之一是纯黑色的剪影，勾勒出起伏的山峦轮廓，右侧有一棵枝叶茂密的树木剪影，左侧是平缓的山坡。画面上方约三分之二被厚重的云层占据，天空呈现出深沉的蓝灰色调，云层纹理丰富，中间部分有微弱的光亮透出，仿佛是暴风雨来临前的压抑景象。整体色调冷峻，对比度极高，营造出一种神秘、阴郁且静谧的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:33:07+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (817).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.33,"observed_resolution":"normal","observation_limits":[],"id":"VP-54cea663359711ee","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-0f03d4541fec2929","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (835).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"画面主体为一名年轻女性的上半身，她头戴紫红色针织帽，身穿浅灰色连帽卫衣，目光向上方凝视。背景昏暗，由深灰色褶皱布料或塑料材质构成，环境占比约四分之三。","analysis":"人物位于画面中央，头部与肩部占据主要视觉空间，背景大面积留白且处于暗部。镜头采用平视角度，光线从上方投射，在面部形成柔和的明暗过渡，帽子的紫红色在冷色调环境中较为突出。整体光色层次丰富，暗部细节隐约可见，营造出一种沉静、压抑的视觉氛围。","prompt":"一名年轻女性的上半身肖像，她头戴一顶紫红色粗针织毛线帽，帽子左侧有一个明显的圆形装饰结。她身穿浅灰色连帽卫衣，领口处可见白色抽绳。人物面部皮肤质感真实，眼神向上方凝视，表情平静且略带忧郁。背景是深灰色的褶皱材质，类似帐篷内壁或塑料布，处于阴影中。光线从上方柔和地照亮人物面部，形成自然的立体感，整体色调偏冷，具有胶片颗粒感，画面氛围沉静而内敛。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:33:15+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (835).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.534,"observed_resolution":"normal","observation_limits":[],"id":"VP-fe620804a1fb5bef","origin":"visual"},{"work_id":"src-649e9b43b303729a","frame_id":"FG-35ef7fcf3966c59d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (832).jpg","source_page":"https://film-grab.com/2014/01/17/post-tenebras-lux/","scene":"两名人物背对镜头行走在碎石小径上，右侧人物背着婴儿背带并拖行一辆倒置的婴儿车，左侧人物背着斜挎包，两侧是茂密的绿色灌木丛。","analysis":"画面采用平视视角，人物位于画面中央，全身可见。左侧人物身形较瘦，右侧人物身形较宽。环境占据画面大部分，两侧植被形成自然框架。光线昏暗，色彩以深绿和土黄为主，人物衣物颜色较浅，与背景形成对比。","prompt":"两名人物背对镜头行走在一条碎石小径上，左侧人物身穿浅色上衣和深色长裤，背着斜挎包，右侧人物身穿黄色上衣和牛仔裤，背着婴儿背带，拖行一辆倒置的婴儿车。小径两侧是茂密的绿色灌木丛，环境显得幽暗。光线昏暗，色彩以深绿和土黄为主，人物衣物颜色较浅，与背景形成对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:33:26+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (832).jpg","observed_dimensions":[944,720],"source_thumbnail_dimensions":[500,381],"source_image_match_mae":0.547,"observed_resolution":"normal","observation_limits":[],"id":"VP-598a7217dd6eb579","origin":"visual"}]};